class Solution {
public:
    bool hasValidPath(vector<vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size();
        if (grid[0][0] != '(' || grid[m-1][n-1] != ')') return false;
        int maxb = m + n;
        vector<vector<vector<bool>>> dp(m, vector<vector<bool>>(n, vector<bool>(maxb + 1, false)));
        dp[0][0][1] = true;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                int d = grid[i][j] == '(' ? 1 : -1;
                for (int b = 0; b <= maxb; b++) {
                    bool ok = false;
                    if (i > 0 && b - d >= 0 && b - d <= maxb && dp[i-1][j][b - d]) ok = true;
                    if (j > 0 && b - d >= 0 && b - d <= maxb && dp[i][j-1][b - d]) ok = true;
                    if (ok) dp[i][j][b] = true;
                }
            }
        return dp[m-1][n-1][0];
    }
};

