class Solution {
public:
    bool hasValidPath(vector<vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size();
        if (grid[0][0] != '(' || grid[m-1][n-1] != ')') return false;
        int W = (m + n) / 64 + 2;
        vector<vector<vector<uint64_t>>> dp(m, vector<vector<uint64_t>>(n, vector<uint64_t>(W, 0)));
        auto setBit = [&](vector<uint64_t>& v, int b) { v[b >> 6] |= 1ULL << (b & 63); };
        auto getBit = [&](vector<uint64_t>& v, int b) { return (v[b >> 6] >> (b & 63)) & 1ULL; };
        setBit(dp[0][0], 1);
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                int d = grid[i][j] == '(' ? 1 : -1;
                if (i == 0 && j == 0) continue;
                for (int w = 0; w < W; w++) {
                    uint64_t acc = 0;
                    if (i > 0) acc |= dp[i-1][j][w];
                    if (j > 0) acc |= dp[i][j-1][w];
                    if (!acc) continue;
                    uint64_t out = d == 1 ? acc << 1 : acc >> 1;
                    if (d == 1 && (acc >> 63)) setBit(dp[i][j], (w + 1) * 64);
                    dp[i][j][w] |= out;
                }
            }
        return getBit(dp[m-1][n-1], 0);
    }
};

