class Solution {
    public boolean hasValidPath(char[][] grid) {
        int m = grid.length, n = grid[0].length;
        if (grid[0][0] != '(' || grid[m-1][n-1] != ')') return false;
        java.util.BitSet[][] dp = new java.util.BitSet[m][n];
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) dp[i][j] = new java.util.BitSet();
        dp[0][0].set(1);
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                java.util.BitSet cur = new java.util.BitSet();
                if (i > 0) cur.or(dp[i-1][j]);
                if (j > 0) cur.or(dp[i][j-1]);
                java.util.BitSet nx = new java.util.BitSet();
                for (int b = cur.nextSetBit(0); b >= 0; b = cur.nextSetBit(b + 1)) {
                    int nb = b + (grid[i][j] == '(' ? 1 : -1);
                    if (nb >= 0) nx.set(nb);
                }
                dp[i][j] = nx;
            }
        return dp[m-1][n-1].get(0);
    }
}

