var hasValidPath = function(grid) {
    const m = grid.length, n = grid[0].length;
    if (grid[0][0] !== '(' || grid[m-1][n-1] !== ')') return false;
    const dp = Array.from({length: m}, () => Array.from({length: n}, () => 0n));
    dp[0][0] = 2n;
    const full = (1n << BigInt(m + n + 1)) - 1n;
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++) {
            if (i === 0 && j === 0) continue;
            let cur = 0n;
            if (i > 0) cur |= dp[i-1][j];
            if (j > 0) cur |= dp[i][j-1];
            dp[i][j] = grid[i][j] === '(' ? (cur << 1n) & full : cur >> 1n;
        }
    return (dp[m-1][n-1] & 1n) !== 0n;
};
